test('all ten baseline fixed corpora preserve every initial field; Aliens alone appends a resolution to its six-record audit',async()=>{
  assert.equal(Object.keys(frozen.audits).length,10);
  for(const[file,old]of Object.entries(frozen.audits))historical(await json(file),old,file);
  const current=cases[0],before=frozen.audits[current.audit],audit=await json(current.audit);
  assert.deepEqual(audit.records.map(row=>row.problemId),['ioi2016_molecules','ioi2016_railroad','ioi2016_shortcut','ioi2016_paint','ioi2016_messy','ioi2016_aliens']);
  assert.equal(before.records.length,6);assert.deepEqual(audit.status,before.status);
  assert.equal(audit.status.solutionReviewedCount,6);assert.equal(audit.status.statementVerifiedCount,6);
  assert.equal(audit.status.coveredCount,0);assert.equal(audit.status.fullImplementationValidatedCount,0);
  assert.equal(audit.status.fixedCorpusResearchComplete,true);assert.equal(audit.status.fixedCorpusCoverageComplete,false);
  assert.equal(audit.status.globalCoverageComplete,false);assert.equal(audit.status.globalLearningComplete,false);
  const row=audit.records.find(row=>match(row,current)),old=before.records.find(row=>match(row,current));
  assert.equal(old.reviewStatus,'verified');assert.equal(old.classification,'missing-technique');
  assert.equal(old.completedApiCoverage,false);assert.equal(row.completedApiCoverage,false);
  assert.equal(old.technicalFindings.fullImplementationValidated,false);assert.equal(row.technicalFindings.fullImplementationValidated,false);
  assert.equal(isCorpusSolutionReviewed(old),true);assert.equal(isCorpusSolutionReviewed(row),true);
  assert.equal(old.materialStatus.solution,'retrieved-and-reviewed');assert(!Object.hasOwn(row,'subsequentSolutionReviews'));
  assert.deepEqual(Object.keys(row).filter(key=>!Object.hasOwn(old,key)),['resolution']);
  for(const other of audit.records.filter(row=>!match(row,current))){
    const initial=before.records.find(row=>row.problemId===other.problemId);
    // Future legitimate resolutions may be appended, but the initial production
    // flags, research evidence and every pre-existing resolution remain fixed.
    for(const key of Object.keys(initial))assert.deepEqual(other[key],initial[key]);
    assert.equal(other.completedApiCoverage,false);
  }
});

