function coverageData(flow,techniques,references,walks,preflightPassed=true){return{techniques,references,walks,preflightPassed,isWalkValid:(row,id)=>{
  try{const value=flow.walkFromRoot(row.choices,row.entryGraphId);return flow.getGraph(row.entryGraphId).entry===true&&value.consumed===row.choices.length&&value.current.type==='result'&&candidates(value).includes(id)
    &&JSON.stringify(value.steps.map(({graph,node,answer})=>({graph,node,answer})))===JSON.stringify(row.steps);}catch{return false;}}};}
const selection=(plan,current)=>({...plan.corpora.find(row=>row.auditFile===current.audit),cutoff:plan.cutoff});
function assessed(audit,data,chosen,reviewed,covered){const result=assessCorpus(audit,data,chosen);assert.deepEqual(result.errors,[]);assert.equal(result.totalProblems,6);assert.equal(result.reviewedProblems,reviewed);assert.equal(result.coveredProblems,covered);assert.equal(result.researchComplete,reviewed===6);assert.equal(result.coverageComplete,reviewed===6&&covered===6);return result;}

test('Aliens production coverage requires complete root walk, actual source and reviewed article; initial research6/API0 stays historical',async()=>{
  const {flow}=await implementation;const[plan,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const data=coverageData(flow,techniques,references,walks),current=cases[0],live=await json(current.audit),chosen=selection(plan,current);
  assessed(frozen.audits[current.audit],data,chosen,6,0);const actual=assessCorpus(live,data,chosen);assert.deepEqual(actual.errors,[]);const covered=actual.coveredProblems;assert(covered>=1);assert(actual.records.find(r=>r.problemId===current.problemId).resolved);assessed(live,data,chosen,6,covered);
  const noResolution=structuredClone(live);delete noResolution.records.find(row=>match(row,current)).resolution;assessed(noResolution,data,chosen,6,covered-1);
  assessed(live,{...data,references:references.filter(row=>row.techniqueId!==current.id)},chosen,6,covered-1);
  assessed(live,{...data,techniques:techniques.filter(row=>row.id!==current.id)},chosen,6,covered-1);
  const draft=structuredClone(techniques);draft.find(row=>row.id===current.id).status='draft';assessed(live,{...data,techniques:draft},chosen,6,covered-1);
  const noExample=walks.filter(row=>!(match(row,current)&&row.expectedTechniqueIds.includes(current.id)));assessed(live,coverageData(flow,techniques,references,noExample),chosen,6,covered-1);
  const wrong=structuredClone(references);wrong.find(row=>row.techniqueId===current.id).url='https://example.invalid/wrong-original';assessed(live,{...data,references:wrong},chosen,6,covered-1);
  const badWalk=structuredClone(walks);badWalk.find(row=>match(row,current)&&row.expectedTechniqueIds.includes(current.id)).choices=[...current.prefix,'no'];assessed(live,coverageData(flow,techniques,references,badWalk),chosen,6,covered-1);
  const badSteps=structuredClone(walks);badSteps.find(row=>match(row,current)&&row.expectedTechniqueIds.includes(current.id)).steps.at(-1).answer='unknown';assessed(live,coverageData(flow,techniques,references,badSteps),chosen,6,covered-1);
});

test('coverage plan and manual source ledger preserve fixed identities and only genuinely resolved gap states may change',async()=>{
  const {flow}=await implementation;const[plan,sources,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),json('data/sources.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const before=frozenJson('data/coverage-plan.json'),data=coverageData(flow,techniques,references,walks);
  assert.equal(plan.cutoff,before.cutoff);assert.equal(plan.policy,before.policy);
  for(const row of before.corpora)assert.deepEqual(plan.corpora.find(fresh=>fresh.id===row.id),row,'old fixed corpus selection remains exact');
  for(const old of before.knownGaps){const fresh=plan.knownGaps.find(gap=>gap.id===old.id);assert(fresh);
    for(const [key,value]of Object.entries(old))if(key!=='state')assert.deepEqual(fresh[key],value,'old gap '+old.id+'/'+key);
    if(fresh.state!==old.state){assert.equal(fresh.state,'resolved');let legitimate=false;
      for(const corpus of plan.corpora){const audit=await json(corpus.auditFile),rows=audit.records.filter(row=>row.gap?.id===old.id||row.gap?.neededTechniqueIds?.includes(old.id));if(!rows.length)continue;
        const result=assessCorpus(audit,data,{...corpus,cutoff:plan.cutoff});assert.deepEqual(result.errors,[]);
        legitimate||=rows.every(row=>result.records.find(record=>record.problemId===row.problemId)?.resolved===true);}
      assert(legitimate,'changed state is supported by actual resolution/article/reference/root walk');}}
  assert.equal(plan.knownGaps.find(gap=>gap.id===cases[0].id).state,'resolved');
  const previousSources=frozenJson('data/sources.json');assert.deepEqual(sources.map(row=>row.id),previousSources.map(row=>row.id));
  for(const old of previousSources){const row=sources.find(row=>row.id===old.id);
    for(const [key,value]of Object.entries(old))if(old.id==='ioi'&&key==='notes')assert(row.notes.startsWith(value));else assert.deepEqual(row[key],value,'source '+old.id+'/'+key);}
  const ioi=sources.find(row=>row.id==='ioi');assert.equal(ioi.method,'manual');assert.equal(ioi.status,'partially-audited');assert.equal(ioi.adapter,null);assert(/Aliens|宇宙人/.test(ioi.notes));
  const progress=await readCorpusProgress(site,sources),chosen=progress.filter(row=>row.problemId.startsWith('ioi2016_'));
  assert.equal(chosen.length,6);assert.equal(chosen.filter(row=>row.statementVerified).length,6);assert.equal(chosen.filter(row=>row.solutionVerified).length,6);
});

// Mutations replace mirror symlinks before writing. Original source files are
// never opened for writing; dotfiles (including forbidden .env*) are skipped.
async function mirrorDirectory(source,destination){await mkdir(destination,{recursive:true});for(const entry of await readdir(source,{withFileTypes:true})){
  if(entry.name.startsWith('.'))continue;const from=path.join(source,entry.name),to=path.join(destination,entry.name);
  if(entry.isDirectory())await mirrorDirectory(from,to);else await symlink(from,to);}}
test('invalid visible C++ fails actual product preflight and gates production coverage to zero across every fixed corpus',async()=>{
  const {flow}=await implementation;const[plan,techniques,references,walks]=await Promise.all([json('data/coverage-plan.json'),collections(/^techniques-.*\.json$/),collections(/^references-.*\.json$/),json('data/problem-walks.json')]);
  const current=cases[0],relative='src/content/docs/techniques/'+current.id+'.mdx',source=await readFile(path.join(site,relative),'utf8'),originalHash=bytesHash(source);
  const mirror=await mkdtemp(path.join(tmpdir(),'flowchartcp-ioi2016-aliens-preflight-'));
  try{await mirrorDirectory(path.join(site,'data'),path.join(mirror,'data'));await mirrorDirectory(path.join(site,'src/content/docs'),path.join(mirror,'src/content/docs'));
    for(const directory of ['public','research','vendor'])await symlink(path.join(site,directory),path.join(mirror,directory),'dir');
    const clean=await validateSite(mirror);assert.deepEqual(clean.errors,[],'unmodified isolated mirror passes actual preflight');
    const target=path.join(mirror,relative),broken=source.replace(/^```cpp\s*\n[\s\S]*?^```\s*$/m,'```cpp\n```');assert.notEqual(broken,source);await unlink(target);await writeFile(target,broken);
    const invalid=await validateSite(mirror);assert(invalid.errors.some(error=>error.includes(current.id)&&/再利用可能な実装例/.test(error)),'actual invalid fence rejected');
    for(const corpus of plan.corpora){const audit=await json(corpus.auditFile),chosen={...corpus,cutoff:plan.cutoff};
      const good=assessCorpus(audit,coverageData(flow,techniques,references,walks),chosen),bad=assessCorpus(audit,coverageData(flow,techniques,references,walks,invalid.errors.length===0),chosen);
      assert.deepEqual(good.errors,[]);assert.deepEqual(bad.errors,[]);assert.equal(bad.coveredProblems,0,corpus.id+': failed content gate means zero production coverage');assert.equal(bad.reviewedProblems,good.reviewedProblems);}
  }finally{await rm(mirror,{recursive:true,force:true});}
  assert.equal(bytesHash(await readFile(path.join(site,relative))),originalHash,'real article bytes unchanged');
});
